use forge_template :: Element ; use serde_json :: to_string_pretty ; use crate :: context :: ContextMessage ; use crate :: conversation :: Conversation ; use forge_test_kit :: json_fixture ; use super :: * ; # [doc = " Creates a tools section displaying all available tools"] fn create_tools_section (conversation : & Conversation) -> Element { let section = Element :: new ("div.section") . append (Element :: new ("h2") . text ("Tools")) ; if let Some (context) = & conversation . context { if ! context . tools . is_empty () { let tools_elm = Element :: new ("div.tools-section") . append (context . tools . iter () . map (| tool | { Element :: new ("details.message-card.message-tool") . append (Element :: new ("summary") . append (Element :: span (tool . name . to_string ())) ,) . append (Element :: new ("div.main-content") . append (Element :: new ("p") . append (Element :: new ("strong") . text (tool . description . to_string ()) ,)) . append (Element :: new ("pre") . text (to_string_pretty (& tool . input_schema) . unwrap_or_default () ,)) ,) })) ; section . append (tools_elm) } else { section . append (Element :: new ("p") . text ("No tools available")) } } else { section . append (Element :: new ("p") . text ("No tools available")) } }